"use client";

import { createClient } from "@/lib/supabase/client";
import type { Announcement, Category, Course, Profile, Resource, TimetableEntry, TimetableKind } from "@/lib/types";
import { useMutation, useQueryClient, QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { Bell, BookOpen, CalendarDays, Clock, Download, FileText, FolderOpen, Heart, Home, LayoutDashboard, List, LogOut, MapPin, Megaphone, Menu, Pencil, Plus, Search, Trash2, Upload, User, X } from "lucide-react";
import { useRouter } from "next/navigation";
import { FormEvent, useEffect, useMemo, useState } from "react";

const categories: Category[] = ["Lecture Notes", "Past Questions", "Assignments"];
const nav = [{ id: "home", label: "Home", icon: Home }, { id: "resources", label: "Resources", icon: FolderOpen }, { id: "announcements", label: "Announcements", icon: Bell }, { id: "timetable", label: "Timetable", icon: CalendarDays }, { id: "favorites", label: "Favorites", icon: Heart }];

export function Dashboard(props: { profile: Profile; initialResources: Resource[]; initialAnnouncements: Announcement[]; initialFavorites: string[]; initialTimetable: TimetableEntry[]; initialCourses: Course[] }) {
  const [client] = useState(() => new QueryClient());
  return <QueryClientProvider client={client}><DashboardInner {...props}/></QueryClientProvider>;
}

function DashboardInner({ profile, initialResources, initialAnnouncements, initialFavorites, initialTimetable, initialCourses }: { profile: Profile; initialResources: Resource[]; initialAnnouncements: Announcement[]; initialFavorites: string[]; initialTimetable: TimetableEntry[]; initialCourses: Course[] }) {
  const router = useRouter(); const queryClient = useQueryClient(); const supabase = createClient();
  const [page, setPage] = useState("home"); const [menu, setMenu] = useState(false); const [accountMenu, setAccountMenu] = useState(false); const [query, setQuery] = useState(""); const [category, setCategory] = useState("All");
  const [resources, setResources] = useState(initialResources); const [courses, setCourses] = useState(initialCourses); const [selectedCourse, setSelectedCourse] = useState<Course | null>(null); const [announcements, setAnnouncements] = useState(initialAnnouncements); const [timetable, setTimetable] = useState(initialTimetable); const [favorites, setFavorites] = useState(new Set(initialFavorites)); const [modal, setModal] = useState<"resource" | "announcement" | "timetable" | "courses" | null>(null); const [editing, setEditing] = useState<Resource | null>(null); const [notice, setNotice] = useState("");
  const [downloadedIds, setDownloadedIds] = useState<Set<string>>(new Set());
  useEffect(() => { try { const saved = JSON.parse(localStorage.getItem(`easy_downloads_${profile.id}`) || "[]"); if (Array.isArray(saved)) setDownloadedIds(new Set(saved)); } catch {} }, [profile.id]);
  const filtered = useMemo(() => resources.filter(r => `${r.title} ${r.course_code} ${r.course_name} ${r.department}`.toLowerCase().includes(query.toLowerCase()) && (category === "All" || r.category === category) && (page !== "favorites" || favorites.has(r.id))), [resources, query, category, page, favorites]);
  const flash = (text: string) => { setNotice(text); setTimeout(() => setNotice(""), 2500); };
  const addDownloaded = (id: string) => { setDownloadedIds(prev => { if (prev.has(id)) return prev; const next = new Set(prev); next.add(id); localStorage.setItem(`easy_downloads_${profile.id}`, JSON.stringify([...next])); return next; }); };
  const favorite = useMutation({ mutationFn: async (r: Resource) => { if (favorites.has(r.id)) { const { error } = await supabase.from("favorites").delete().eq("user_id", profile.id).eq("resource_id", r.id); if (error) throw error; } else { const { error } = await supabase.from("favorites").insert({ user_id: profile.id, resource_id: r.id }); if (error) throw error; } }, onSuccess: (_, r) => { setFavorites(old => { const n = new Set(old); if (n.has(r.id)) n.delete(r.id); else n.add(r.id); return n; }); queryClient.invalidateQueries(); } });
  async function download(r: Resource) { const { data, error } = await supabase.storage.from("resources").createSignedUrl(r.storage_path, 60, { download: r.title }); if (error) return flash(error.message); await supabase.rpc("increment_download", { resource_id: r.id }); addDownloaded(r.id); if (data?.signedUrl) window.open(data.signedUrl, "_blank", "noopener,noreferrer"); setResources(x => x.map(v => v.id === r.id ? { ...v, downloads: v.downloads + 1 } : v)); }
  async function downloadAll(items: Resource[]) {
    if (!items.length) return;
    flash(`Preparing ${items.length} files...`);
    const signed = await Promise.all(items.map(async item => {
      const { data, error } = await supabase.storage.from("resources").createSignedUrl(item.storage_path, 120, { download: item.title });
      return error || !data ? null : { item, url: data.signedUrl };
    }));
    const available = signed.filter((result): result is { item: Resource; url: string } => result !== null);
    available.forEach(({ url }, index) => {
      setTimeout(() => {
        const anchor = document.createElement("a");
        anchor.href = url;
        anchor.download = "";
        anchor.style.display = "none";
        document.body.appendChild(anchor);
        anchor.click();
        anchor.remove();
      }, index * 250);
    });
    await Promise.all(available.map(({ item }) => supabase.rpc("increment_download", { resource_id: item.id })));
    available.forEach(({ item }) => addDownloaded(item.id));
    const downloadedIds = new Set(available.map(({ item }) => item.id));
    setResources(current => current.map(item => downloadedIds.has(item.id) ? { ...item, downloads: item.downloads + 1 } : item));
    flash(available.length === items.length ? `${items.length} downloads started. Allow multiple downloads if Chrome asks.` : `${available.length} of ${items.length} downloads started.`);
  }
  async function remove(r: Resource) { if (!confirm(`Delete ${r.title}?`)) return; const { error } = await supabase.from("resources").delete().eq("id", r.id); if (error) return flash(error.message); await supabase.storage.from("resources").remove([r.storage_path]); setResources(x => x.filter(v => v.id !== r.id)); flash("Resource deleted."); }
  async function removeTimetable(entry: TimetableEntry) { if (!confirm(`Delete ${entry.course_name} from the timetable?`)) return; const { error } = await supabase.from("timetable_entries").delete().eq("id", entry.id); if (error) return flash(error.message); setTimetable(items => items.filter(item => item.id !== entry.id)); flash("Timetable entry deleted."); }
  async function signOut() { await supabase.auth.signOut(); router.push("/login"); router.refresh(); }
  const title = page === "home" ? `Hi, ${profile.full_name.split(" ")[0]}` : page[0].toUpperCase() + page.slice(1);
  return <div className="app-shell"><aside className={menu ? "sidebar open" : "sidebar"}><div className="app-brand"><span><BookOpen/></span><b>Easy</b><button onClick={() => setMenu(false)}><X/></button></div><div className="role-label">{profile.role === "course_rep" ? "COURSE REP PORTAL" : "STUDENT PORTAL"}</div><nav>{nav.filter(n => profile.role !== "course_rep" || n.id !== "favorites").map(n => <button key={n.id} className={page === n.id ? "active" : ""} onClick={() => { setPage(n.id); setMenu(false); }}><n.icon/>{n.label}</button>)}{profile.role === "course_rep" && <><button className={page === "courses" ? "active" : ""} onClick={() => { setPage("courses"); setMenu(false); }}><BookOpen/>Manage Courses</button><button className={page === "manage" ? "active" : ""} onClick={() => { setPage("manage"); setMenu(false); }}><LayoutDashboard/>Manage content</button><button className={page === "favorites" ? "active" : ""} onClick={() => { setPage("favorites"); setMenu(false); }}><Heart/>Favorites</button></>}</nav><div className="sidebar-user"><span>{profile.full_name.split(" ").map(x => x[0]).slice(0,2).join("")}</span><div><b>{profile.full_name}</b><small>{profile.role === "course_rep" ? "Course Representative" : "Student"} · Level {profile.level}</small></div><button onClick={signOut} title="Sign out"><LogOut/></button></div></aside>{menu && <button className="backdrop" onClick={() => setMenu(false)}/>}<main className="app-main"><header className="app-header"><button className="menu-btn" onClick={() => setMenu(true)}><Menu/></button><div className="global-search"><Search/><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search courses, resources, departments..."/></div><button className="icon-button"><Bell/><i/></button><div className="account-menu-wrap"><button className="top-avatar" onClick={() => setAccountMenu(!accountMenu)} aria-label="Open account menu" aria-expanded={accountMenu}>{profile.full_name[0]}</button>{accountMenu&&<><button className="account-menu-shade" onClick={()=>setAccountMenu(false)} aria-label="Close account menu"/><div className="account-dropdown"><div className="account-summary"><span>{profile.full_name[0]}</span><div><b>{profile.full_name}</b><small>{profile.department} · Level {profile.level}</small></div></div><button onClick={()=>{setPage("profile");setAccountMenu(false)}}><User/>Profile</button><button onClick={signOut}><LogOut/>Sign out</button></div></>}</div></header><div className="content"><div className="content-title"><div>{page === "resources" && selectedCourse ? <div className="active-course-heading"><button onClick={() => setSelectedCourse(null)}>← All Courses</button><h1>{selectedCourse.name}</h1><p>{selectedCourse.code}</p></div> : <><h1>{title}</h1><p>{page === "home" ? "Here’s what’s happening with your courses." : page === "manage" ? "Upload and manage academic content." : `Manage your ${page}.`}</p></>}</div>{profile.role === "course_rep" && page === "courses" && <div className="title-actions"><button className="primary-action" onClick={() => setModal("courses")}><Plus/>Set up courses</button></div>}{profile.role === "course_rep" && page === "manage" && <div className="title-actions"><button className="secondary-action" onClick={() => setModal("timetable")}><CalendarDays/>Add timetable</button><button className="secondary-action" onClick={() => setModal("announcement")}><Megaphone/>Post announcement</button><button className="primary-action" onClick={() => { setEditing(null); setModal("resource"); }}><Plus/>Upload resource</button></div>}</div>{page === "home" && <HomeView resources={resources} announcements={announcements} favorites={favorites.size} downloads={downloadedIds.size} rep={profile.role === "course_rep"} go={setPage}/>} {page === "resources" && <CourseResourcesView courses={courses} resources={filtered} totalFiles={resources.length} downloadedIds={downloadedIds} selectedCourse={selectedCourse} setSelectedCourse={setSelectedCourse} favorites={favorites} onFavorite={r => favorite.mutate(r)} onDownload={download} onDownloadAll={downloadAll}/>} {page === "favorites" && <ResourceView resources={filtered} favorites={favorites} category={category} setCategory={setCategory} onFavorite={r => favorite.mutate(r)} onDownload={download}/>} {page === "courses" && <ManageCoursesView courses={courses} resources={resources}/>} {page === "announcements" && <AnnouncementView announcements={announcements}/>} {page === "timetable" && <TimetableView entries={timetable} canManage={profile.role === "course_rep"} onDelete={removeTimetable}/>} {page === "profile" && <ProfileView profile={profile} onSaved={() => flash("Profile updated.")}/>} {page === "manage" && <ManageView resources={filtered} onEdit={r => { setEditing(r); setModal("resource"); }} onDelete={remove}/>}</div></main>{modal === "courses" && <CoursesModal profile={profile} existing={courses} onClose={() => setModal(null)} onSaved={created => { setCourses(old => [...old, ...created].sort((a,b) => a.name.localeCompare(b.name))); setModal(null); flash("Courses saved."); }}/>} {modal === "resource" && <ResourceModal profile={profile} courses={courses} resource={editing} onClose={() => setModal(null)} onSaved={r => { setResources(old => editing ? old.map(x => x.id === r.id ? r : x) : [r, ...old]); setModal(null); flash(editing ? "Resource updated." : "Resource uploaded."); }}/>} {modal === "announcement" && <AnnouncementModal profile={profile} onClose={() => setModal(null)} onSaved={a => { setAnnouncements(x => [a, ...x]); setModal(null); flash("Announcement posted."); }}/>} {modal === "timetable" && <TimetableModal profile={profile} onClose={() => setModal(null)} onSaved={entry => { setTimetable(x => [...x, entry]); setModal(null); flash("Timetable entry added."); }}/>} {notice && <div className="notice">{notice}</div>}</div>;
}

function HomeView({ resources, announcements, favorites, downloads, rep, go }: { resources: Resource[]; announcements: Announcement[]; favorites: number; downloads: number; rep: boolean; go: (p:string)=>void }) { return <><div className="stats-grid"><Stat icon={<FolderOpen/>} label="Resources" value={resources.length}/><Stat icon={<Heart/>} label="Favorites" value={favorites}/><Stat icon={<Download/>} label="Downloads" value={downloads}/><Stat icon={<Megaphone/>} label="Announcements" value={announcements.length}/></div><div className="dashboard-grid"><section><div className="section-head"><h2>Latest resources</h2><button onClick={()=>go("resources")}>View all</button></div><div className="compact-list">{resources.slice(0,5).map(r=><div key={r.id}><span className="file-icon"><FileText/></span><div><b>{r.title}</b><small>{r.course_code} · {r.category}</small></div><time>{new Date(r.created_at).toLocaleDateString()}</time></div>)}{!resources.length&&<Empty text="No resources have been uploaded yet."/>}</div></section><section><div className="section-head"><h2>Recent announcements</h2><button onClick={()=>go("announcements")}>View all</button></div><div className="announcement-mini">{announcements.slice(0,3).map(a=><article key={a.id}><Megaphone/><div><b>{a.title}</b><p>{a.message}</p><small>{new Date(a.created_at).toLocaleDateString()}</small></div></article>)}{!announcements.length&&<Empty text="No announcements yet."/>}</div></section></div>{rep&&<div className="rep-banner"><div><b>Course Representative tools</b><p>Upload materials, post updates, and monitor engagement.</p></div><button onClick={()=>go("manage")}>Open management</button></div>}</> }
function Stat({icon,label,value}:{icon:React.ReactNode;label:string;value:number}){return <article className="stat-card"><span>{icon}</span><div><small>{label}</small><b>{value}</b></div></article>}
function OfflineLibrary({count,total}:{count:number;total:number}){const pct=total?Math.round((count/total)*100):0;return <article className="offline-library-card"><h3>Offline library</h3><div className="offline-stat"><b>{count}</b><span>of {total} files saved</span></div><div className="offline-bar"><div style={{width:`${pct}%`}}/></div><p>Saved files open without data.</p></article>}
function formatBytes(bytes:number){if(!bytes)return"0 B";const units=["B","KB","MB","GB"];const index=Math.min(Math.floor(Math.log(bytes)/Math.log(1024)),units.length-1);return `${(bytes/1024**index).toFixed(index?1:0)} ${units[index]}`}
function timeAgo(value:string){const seconds=Math.floor((Date.now()-new Date(value).getTime())/1000);if(seconds<60)return"just now";if(seconds<3600)return`${Math.floor(seconds/60)}m ago`;if(seconds<86400)return`${Math.floor(seconds/3600)}h ago`;if(seconds<604800)return`${Math.floor(seconds/86400)}d ago`;return new Date(value).toLocaleDateString()}
function CourseResourcesView({courses,resources,totalFiles,downloadedIds,selectedCourse,setSelectedCourse,favorites,onFavorite,onDownload,onDownloadAll}:{courses:Course[];resources:Resource[];totalFiles:number;downloadedIds:Set<string>;selectedCourse:Course|null;setSelectedCourse:(course:Course|null)=>void;favorites:Set<string>;onFavorite:(r:Resource)=>void;onDownload:(r:Resource)=>void;onDownloadAll:(resources:Resource[])=>void}){const[activeCategory,setActiveCategory]=useState<Category>("Lecture Notes");if(selectedCourse){const files=resources.filter(resource=>resource.course_id===selectedCourse.id||(!resource.course_id&&resource.course_code===selectedCourse.code));return <div className="course-detail-layout"><main><div className="resource-tabs">{categories.map(category=><button key={category} className={activeCategory===category?"active":""} onClick={()=>setActiveCategory(category)}>{category}<span>{files.filter(file=>file.category===category).length}</span></button>)}</div>{(()=>{const categoryFiles=files.filter(file=>file.category===activeCategory);return <section className="resource-category"><div className="section-head"><h2>{activeCategory}</h2><div className="category-actions"><span>{categoryFiles.length} files</span>{categoryFiles.length>0&&<button onClick={()=>onDownloadAll(categoryFiles)}><Download/>Download all ({categoryFiles.length})</button>}</div></div>{categoryFiles.length?<div className="file-table"><div className="file-table-head"><span>FILE</span><span>SIZE</span><span>UPLOADED</span><span></span></div>{categoryFiles.map(resource=><ResourceRow key={resource.id} resource={resource} liked={favorites.has(resource.id)} onFavorite={onFavorite} onDownload={onDownload}/>)}</div>:<div className="category-empty">No {activeCategory.toLowerCase()} uploaded for this course.</div>}</section>})()}</main><div className="right-column"><aside className="course-info-card"><h3>Course</h3><dl><dt>Course code</dt><dd>{selectedCourse.code}</dd><dt>Department</dt><dd>{selectedCourse.department}</dd><dt>Level</dt><dd>Level {selectedCourse.level}</dd><dt>Total files</dt><dd>{files.length}</dd><dt>Total size</dt><dd>{formatBytes(files.reduce((sum,file)=>sum+file.file_size,0))}</dd></dl></aside><OfflineLibrary count={downloadedIds.size} total={totalFiles}/></div></div>}return <div className="course-library-layout"><div className="course-card-grid">{courses.map(course=>{const files=resources.filter(resource=>resource.course_id===course.id||(!resource.course_id&&resource.course_code===course.code));const latest=files.reduce<string|null>((value,file)=>!value||file.created_at>value?file.created_at:value,null);return <button className="course-summary-card" key={course.id} onClick={()=>setSelectedCourse(course)}><h3><i/>{course.name}</h3><p>{course.code}</p><div><span>{files.length} {files.length===1?"file":"files"}</span><small>{formatBytes(files.reduce((sum,file)=>sum+file.file_size,0))}</small><small>{latest?`updated ${timeAgo(latest)}`:"No resources uploaded"}</small></div></button>})}{!courses.length&&<Empty text="Your Course Representative has not created any courses yet."/>}</div><div className="right-column"><aside className="recent-uploads"><h3>Recent uploads</h3>{resources.slice(0,6).map(resource=><button key={resource.id} onClick={()=>setSelectedCourse(courses.find(course=>course.id===resource.course_id)||null)}><b>{resource.title}</b><small>{resource.course_name} · {timeAgo(resource.created_at)}</small></button>)}{!resources.length&&<p>No recent uploads.</p>}</aside><OfflineLibrary count={downloadedIds.size} total={totalFiles}/></div></div>}
function ResourceRow({resource,liked,onFavorite,onDownload}:{resource:Resource;liked:boolean;onFavorite:(r:Resource)=>void;onDownload:(r:Resource)=>void}){const extension=resource.title.split(".").pop()?.toUpperCase()||"FILE";return <div className="file-row"><div className="file-name"><span>{extension}</span><b>{resource.title}</b></div><small>{formatBytes(resource.file_size)}</small><small>{timeAgo(resource.created_at)}</small><div><button className={liked?"row-favorite liked":"row-favorite"} onClick={()=>onFavorite(resource)} title="Favorite"><Heart fill={liked?"currentColor":"none"}/></button><button className="row-download" onClick={()=>onDownload(resource)}>Download</button></div></div>}
function ManageCoursesView({courses,resources}:{courses:Course[];resources:Resource[]}){return <div className="manage-card"><div className="manage-head"><h2>Courses for your department and level</h2><span>{courses.length} of 11 courses</span></div><div className="managed-course-list">{courses.map(course=>{const files=resources.filter(resource=>resource.course_id===course.id);return <article key={course.id}><span><BookOpen/></span><div><b>{course.name}</b><small>{course.code}</small></div><strong>{files.length} files</strong><small>{formatBytes(files.reduce((sum,file)=>sum+file.file_size,0))}</small></article>})}{!courses.length&&<Empty text="Set up the courses your students take."/>}</div></div>}
function CoursesModal({profile,existing,onClose,onSaved}:{profile:Profile;existing:Course[];onClose:()=>void;onSaved:(courses:Course[])=>void}){const supabase=createClient();const remaining=11-existing.length;const[count,setCount]=useState(Math.min(1,remaining));const[error,setError]=useState("");async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=new FormData(e.currentTarget);const rows=Array.from({length:count},(_,index)=>({name:String(form.get(`name-${index}`)||"").trim(),code:String(form.get(`code-${index}`)||"").trim().toUpperCase(),department:profile.department,level:profile.level,created_by:profile.id}));if(rows.some(row=>!row.name||!row.code))return setError("Enter a name and code for every course.");const{data,error}=await supabase.from("courses").insert(rows).select();if(error)setError(error.message);else onSaved(data||[])}return <Modal title="Set up courses" onClose={onClose}><form className="modal-form" onSubmit={submit}><p className="modal-help">Create up to 11 courses for {profile.department}, Level {profile.level}. You already have {existing.length}.</p>{remaining>0&&<label>Number of new courses<select value={count} onChange={event=>setCount(Number(event.target.value))}>{Array.from({length:remaining},(_,index)=><option key={index+1}>{index+1}</option>)}</select></label>}<div className="course-input-list">{Array.from({length:count},(_,index)=><div key={index}><b>Course {existing.length+index+1}</b><div className="form-row"><label>Course name<input name={`name-${index}`} required placeholder="Computer Architecture"/></label><label>Course code<input name={`code-${index}`} required placeholder="CSM 354"/></label></div></div>)}</div>{error&&<p className="form-alert error">{error}</p>}{remaining>0?<button className="primary-action"><Plus/>Save courses</button>:<p className="form-alert error">The maximum of 11 courses has been reached.</p>}</form></Modal>}
function ResourceView({resources,favorites,category,setCategory,onFavorite,onDownload}:{resources:Resource[];favorites:Set<string>;category:string;setCategory:(x:string)=>void;onFavorite:(r:Resource)=>void;onDownload:(r:Resource)=>void}){return <><div className="category-row">{["All",...categories].map(c=><button key={c} className={category===c?"active":""} onClick={()=>setCategory(c)}>{c}</button>)}</div><div className="resource-grid">{resources.map(r=><article className="resource-card" key={r.id}><div className="resource-top"><span><FileText/></span><button className={favorites.has(r.id)?"liked":""} onClick={()=>onFavorite(r)}><Heart fill={favorites.has(r.id)?"currentColor":"none"}/></button></div><span className="category-badge">{r.category}</span><h3>{r.title}</h3><p>{r.description||"Academic resource for this course."}</p><div className="course-line"><b>{r.course_code}</b><span>{r.course_name}</span></div><footer><small><Download/> {r.downloads} downloads</small><button onClick={()=>onDownload(r)}>Download</button></footer></article>)}{!resources.length&&<Empty text="No resources match your search."/>}</div></>}
function AnnouncementView({announcements}:{announcements:Announcement[]}){return <div className="announcement-list">{announcements.map(a=><article key={a.id}><span><Megaphone/></span><div><h3>{a.title}</h3><p>{a.message}</p><small>{new Date(a.created_at).toLocaleString()}</small></div></article>)}{!announcements.length&&<Empty text="No announcements have been posted."/>}</div>}
function ManageView({resources,onEdit,onDelete}:{resources:Resource[];onEdit:(r:Resource)=>void;onDelete:(r:Resource)=>void}){return <div className="manage-card"><div className="manage-head"><h2>Your resource library</h2><span>{resources.length} resources</span></div><div className="resource-table">{resources.map(r=><div key={r.id}><span className="file-icon"><FileText/></span><div><b>{r.title}</b><small>{r.course_code} · {r.category}</small></div><span>{r.downloads} downloads</span><time>{new Date(r.created_at).toLocaleDateString()}</time><div><button onClick={()=>onEdit(r)}><Pencil/></button><button className="danger" onClick={()=>onDelete(r)}><Trash2/></button></div></div>)}{!resources.length&&<Empty text="Upload your first academic resource."/>}</div></div>}
const weekDays = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
function TimetableView({entries,canManage,onDelete}:{entries:TimetableEntry[];canManage:boolean;onDelete:(entry:TimetableEntry)=>void}){const[mode,setMode]=useState<"week"|"list">("week");const[section,setSection]=useState<TimetableKind>("class");const visible=entries.filter(entry=>entry.kind===section).sort((a,b)=>section==="class"?(a.day_of_week??0)-(b.day_of_week??0)||a.start_time.localeCompare(b.start_time):(a.exam_date||"").localeCompare(b.exam_date||"")||a.start_time.localeCompare(b.start_time));return <><div className="timetable-controls"><div><button className={section==="class"?"active":""} onClick={()=>setSection("class")}>Weekly classes</button><button className={section==="exam"?"active":""} onClick={()=>setSection("exam")}>Exams</button></div><div><button className={mode==="week"?"active":""} onClick={()=>setMode("week")}><CalendarDays/>Week</button><button className={mode==="list"?"active":""} onClick={()=>setMode("list")}><List/>List</button></div></div>{mode==="week"&&section==="class"?<div className="week-grid">{weekDays.map((day,index)=><section key={day}><h3>{day.slice(0,3)}</h3>{visible.filter(entry=>entry.day_of_week===index+1).map(entry=><TimetableCard key={entry.id} entry={entry} canManage={canManage} onDelete={onDelete}/>)}</section>)}</div>:<div className="timetable-list">{visible.map(entry=><div key={entry.id} className="schedule-row"><div className="schedule-date">{entry.kind==="class"?weekDays[(entry.day_of_week||1)-1]:new Date(`${entry.exam_date}T00:00:00`).toLocaleDateString(undefined,{month:"short",day:"numeric"})}</div><TimetableCard entry={entry} canManage={canManage} onDelete={onDelete}/></div>)}</div>}{!visible.length&&<Empty text={section==="class"?"No weekly classes have been added.":"No examinations have been scheduled."}/>}</>}
function TimetableCard({entry,canManage,onDelete}:{entry:TimetableEntry;canManage:boolean;onDelete:(entry:TimetableEntry)=>void}){return <article className="timetable-card"><div><b>{entry.course_code}</b><h4>{entry.course_name}</h4></div><p><Clock/>{entry.start_time.slice(0,5)} – {entry.end_time.slice(0,5)}</p><p><MapPin/>{entry.venue||"Venue not set"}</p>{entry.lecturer&&<small>{entry.lecturer}</small>}{canManage&&<button className="schedule-delete" onClick={()=>onDelete(entry)} title="Delete entry"><Trash2/></button>}</article>}
function TimetableModal({profile,onClose,onSaved}:{profile:Profile;onClose:()=>void;onSaved:(entry:TimetableEntry)=>void}){const supabase=createClient();const[kind,setKind]=useState<TimetableKind>("class");const[error,setError]=useState("");async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);const row={kind,course_code:f.get("courseCode"),course_name:f.get("courseName"),department:profile.department,level:profile.level,day_of_week:kind==="class"?Number(f.get("day")):null,exam_date:kind==="exam"?f.get("examDate"):null,start_time:f.get("startTime"),end_time:f.get("endTime"),venue:f.get("venue"),lecturer:f.get("lecturer"),created_by:profile.id};const{data,error}=await supabase.from("timetable_entries").insert(row).select().single();if(error)setError(error.message);else onSaved(data)}return <Modal title="Add timetable entry" onClose={onClose}><form className="modal-form" onSubmit={submit}><div className="role-picker"><button type="button" className={kind==="class"?"selected":""} onClick={()=>setKind("class")}>Weekly class</button><button type="button" className={kind==="exam"?"selected":""} onClick={()=>setKind("exam")}>Exam</button></div><div className="form-row"><label>Course code<input name="courseCode" required placeholder="CS 201"/></label><label>Course name<input name="courseName" required/></label></div>{kind==="class"?<label>Day<select name="day" required>{weekDays.map((day,index)=><option value={index+1} key={day}>{day}</option>)}</select></label>:<label>Exam date<input name="examDate" type="date" required/></label>}<div className="form-row"><label>Start time<input name="startTime" type="time" required/></label><label>End time<input name="endTime" type="time" required/></label></div><div className="form-row"><label>Venue<input name="venue" required/></label><label>Lecturer<input name="lecturer"/></label></div><label>Audience<input value={`${profile.department} · Level ${profile.level}`} disabled readOnly/></label>{error&&<p className="form-alert error">{error}</p>}<button className="primary-action"><CalendarDays/>Add to timetable</button></form></Modal>}
function ProfileView({profile,onSaved}:{profile:Profile;onSaved:()=>void}){const supabase=createClient();async function save(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);const{error}=await supabase.from("profiles").update({full_name:f.get("fullName"),student_id:f.get("studentId")}).eq("id",profile.id);if(!error)onSaved()}return <form className="profile-card" onSubmit={save}><div className="profile-avatar">{profile.full_name[0]}</div><h2>Personal information</h2><div className="form-grid"><label>Full name<input name="fullName" defaultValue={profile.full_name}/></label><label>Student ID<input name="studentId" defaultValue={profile.student_id}/></label><label>Email<input value={profile.email} disabled readOnly/></label><label>Department<input value={profile.department} disabled readOnly/></label><label>Level<input value={`Level ${profile.level}`} disabled readOnly/></label><label>Account type<input value={profile.role==="course_rep"?"Course Representative":"Student"} disabled readOnly/></label></div><button className="primary-action">Save changes</button></form>}
function ResourceModal({profile,courses,resource,onClose,onSaved}:{profile:Profile;courses:Course[];resource:Resource|null;onClose:()=>void;onSaved:(r:Resource)=>void}){const supabase=createClient();const[busy,setBusy]=useState(false);const[error,setError]=useState("");async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError("");const f=new FormData(e.currentTarget);try{let path=resource?.storage_path||"";const file=f.get("file") as File;if(file?.size){const ext=file.name.split(".").pop()?.toLowerCase();if(!["pdf","docx","pptx","zip"].includes(ext||""))throw new Error("Only PDF, DOCX, PPTX, and ZIP files are allowed.");path=`${profile.id}/${crypto.randomUUID()}.${ext}`;const{error}=await supabase.storage.from("resources").upload(path,file);if(error)throw error}if(!path)throw new Error("Choose a file.");const course=courses.find(item=>item.id===f.get("courseId"));if(!course)throw new Error("Select a course.");const title=file?.size?file.name:resource?.title;if(!title)throw new Error("Choose a file.");const row={title,description:"",course_id:course.id,course_code:course.code,course_name:course.name,department:profile.department,level:profile.level,category:f.get("category"),file_url:path,storage_path:path,file_size:file?.size||resource?.file_size||0,uploaded_by:profile.id};const result=resource?await supabase.from("resources").update(row).eq("id",resource.id).select().single():await supabase.from("resources").insert(row).select().single();if(result.error)throw result.error;onSaved(result.data)}catch(err){setError(err instanceof Error?err.message:"Upload failed.")}finally{setBusy(false)}}return <Modal title={resource?"Edit resource":"Upload resource"} onClose={onClose}><form className="modal-form" onSubmit={submit}><label>Course<select name="courseId" required defaultValue={resource?.course_id||""}><option value="" disabled>Select a managed course</option>{courses.map(course=><option key={course.id} value={course.id}>{course.code} — {course.name}</option>)}</select></label><div className="form-row"><label>Department and level<input value={`${profile.department} · Level ${profile.level}`} disabled readOnly/></label><label>Category<select name="category" defaultValue={resource?.category}>{categories.map(c=><option key={c}>{c}</option>)}</select></label></div><label>File (PDF, DOCX, PPTX, ZIP)<input name="file" type="file" required={!resource} accept=".pdf,.docx,.pptx,.zip"/></label>{error&&<p className="form-alert error">{error}</p>}<button className="primary-action" disabled={busy}><Upload/>{busy?"Saving...":"Save resource"}</button></form></Modal>}
function AnnouncementModal({profile,onClose,onSaved}:{profile:Profile;onClose:()=>void;onSaved:(a:Announcement)=>void}){const supabase=createClient();const[error,setError]=useState("");async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);const{data,error}=await supabase.from("announcements").insert({title:f.get("title"),message:f.get("message"),created_by:profile.id,department:profile.department,level:profile.level}).select().single();if(error)setError(error.message);else onSaved(data)}return <Modal title="Post announcement" onClose={onClose}><form className="modal-form" onSubmit={submit}><label>Title<input name="title" required/></label><label>Message<textarea name="message" required rows={6}/></label>{error&&<p className="form-alert error">{error}</p>}<button className="primary-action"><Megaphone/>Post announcement</button></form></Modal>}
function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:React.ReactNode}){return <div className="modal-wrap"><button className="modal-shade" onClick={onClose}/><section className="modal"><header><h2>{title}</h2><button onClick={onClose}><X/></button></header>{children}</section></div>}
function Empty({text}:{text:string}){return <div className="empty"><FolderOpen/><b>{text}</b><small>Content will appear here when available.</small></div>}